mapper.sql:
where shop_code = #{query.shopCode}

  and doc_code = #{query.docCode}


  and doc_type = #{query.docType}


  and source_doc_code like concat('%', #{query.sourceDocCode}, '%')


  and source_doc_type = #{query.sourceDocType}


  and goods_code = #{query.goodsCode}


  and ware_code = #{query.wareCode}


  and batch_code = #{query.batchCode}


  and serial_no = #{query.serialNo}


  and operator = #{query.operator}



  and operate_time >= #{query.operateTimeBegin}


  and operate_time <= #{query.operateTimeEnd}

mapper.select:
select * from (

    ( select ,
             '${suffix}' as table_suffix
        from sdsorder.u_f_ledger_${suffix}
       )

  ) l

select goods_code as goodsCode, ware_code as warehouseCode, batch_code as batchCode,
       sum(-change_qty) as qty
  from sdsorder.u_f_ledger_${tableSuffix}
 where shop_code = #{shopCode}
   and doc_type = 'CK'
   and source_doc_type = 'XSFH'
   and batch_code is not null and batch_code <> ''
   and source_doc_code in
   #{code}
 group by goods_code, ware_code, batch_code

select count(*) from sdsorder.u_f_ledger_${tableSuffix}
 where shop_code = #{shopCode}

   and doc_code = #{docCode}


   and goods_code = #{goodsCode}
